  "claims": [
    {
      "claim": "The query is estradiol 17β-cyclopentylpropionate, and the most transferable direct steroid oral-bioavailability evidence is below 20%: estradiol and progesterone are each about 5% bioavailable in humans, 2-methoxyestradiol is 1–2% clinically, and danazol is 11–19% in the fasted state.",
      "card_ids": ["C06", "C27", "C31", "C32", "C02", "C05", "C30", "C42"]
    },
    {
      "claim": "L4 solubility evidence reinforces the dissolution barrier: estradiol has very low water solubility, and progesterone has aqueous solubility of only about 10–12 µg/mL in buffer; the query is a more lipophilic ester with estimated logD 6.13, so dissolution is expected to be at least as challenging.",
      "card_ids": ["C66", "C61", "C62", "C72"]
    },
    {
      "claim": "High Caco-2 permeability of testosterone (Papp ~5–6 ×10⁻⁵ cm/s) indicates that permeability is not the limiting step for this steroid class; low oral F in related steroids is driven by solubility/dissolution and first-pass metabolism, not by poor membrane permeation.",
      "card_ids": ["C64", "C69", "C70"]
    },
    {
      "claim": "The S-SNEDDS dissolution records and proliposomal progesterone dissolution enhancement are formulation-specific and mostly for other molecules; they do not establish intrinsic F ≥ 20% for the unformulated query ester.",
      "card_ids": ["C63", "C65", "C67", "C68", "C71"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "intestinal_absorption_permeability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C66", "C61", "C62", "C72", "C64", "C69", "C70"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability or intestinal absorption measurement for estradiol cypionate itself.",
    "Dose, formulation, and prandial state for the query are unspecified; a lipophilic ester could theoretically engage lymphatic absorption, but no direct evidence supports this.",
    "L4 solubility and permeability records are for estradiol, progesterone, testosterone, or other molecules, not for the query ester.",
    "Prodrug hydrolysis rate and first-pass metabolism of the cyclopentylpropionate ester are not directly evidenced.",
    "The L3 estradiol exposure record is from a conjugated estrogen product, not estradiol cypionate, so its quantitative relevance is limited."
  ],
  "decision_summary": "Predicted low with high confidence: the query is estradiol 17β-cyclopentylpropionate, and the most transferable steroid evidence (estradiol ~5%, 2-methoxyestradiol 1–2%, progesterone ~5%, danazol 11–19%) supports F < 20%. L4 solubility evidence reinforces the dissolution barrier, while high steroid permeability does not overcome the low-F evidence. No new evidence supports F ≥ 20%."
}

